  --color-code-surface: var(--well-bottom);
  border-radius: var(--code-frame-radius);
  background-color: var(--well-bottom);
  background-image: linear-gradient(180deg, var(--well-top), var(--well-bottom) 40%);
  box-shadow: inset 0 0 0 1px var(--well-contour),
    inset 0 2px 0 var(--well-lip),
    0 1px 2px light-dark(oklch(18% 0 none / .04), #0000004d),
    0 6px 18px -12px light-dark(oklch(25% .01 70 / .12), #00000073);
  border: 0;
  position: relative;

  &:before {
    z-index: 1;
    border-radius: inherit;
    background-image: linear-gradient(160deg, var(--well-rim), var(--well-rim-far) 45%);
    pointer-events: none;
    content: "";
    padding: 1px;
    position: absolute;
    inset: 0;
    mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
  }

  & .code-wrapper, & .code-bar {
    background-color: #0000;
  }

  & .code-wrapper {
    padding-block: calc(var(--prose-line, 1.75rem) * .625);
  }

  & .line {
    padding-inline: var(--well-inset, 1.25rem);
  }

  & :is(.code-line-add, .code-line-remove) {
    padding-left: calc(var(--well-inset, 1.25rem) - 2px);
  }

  & .code-bar {
    min-height: calc(var(--prose-line, 2rem) * 1.25);
    border-bottom: 1px solid var(--well-seam);
    box-shadow: none;
  }

  & :is(.code-window-controls, .code-tab-icon) {
    display: none;
  }

  & .code-file-label {
    padding-left: var(--well-inset, 1.25rem);
    font-family: var(--font-family-mono);
    color: var(--well-label);
    font-size: .75rem;
  }

  & .code-bar-tabs {
    padding-left: calc(var(--well-inset, 1.25rem) - .625rem - 1px);
    mask-image: linear-gradient(90deg, #000 calc(100% - 1.5rem), #0000);
  }

  & .code-bar-actions {
    padding-inline-end: calc(var(--well-inset, 1.25rem) - (var(--well-copy) - 1rem) / 2);
  }

  &.code-plain > .code-wrapper {
    padding-inline-end: 0;
  }

  &.code-plain .line {
    padding-inline-end: calc(var(--well-inset, 1.25rem) + 1.75rem);
  }

  & .code-tab:after {
    background-color: var(--well-seam);
    box-shadow: none;
  }

  & .code-block:not(:has(.code-line-add, .code-line-remove)) > .line:before {
    content: "​";
    width: auto;
    margin: 0;
    padding: 0;
    display: inline;
  }

  & .code-copy-button {
    color: var(--well-control);
    transition: color .36s;

    &:hover {
      color: var(--well-label);
      background-color: #0000;
    }
  }

  & .code-bar-actions:before {
    content: none;
  }

  & .code-copy-corner {
    top: calc(var(--prose-line, 1.75rem) * .625 + var(--prose-code-line, 1.375rem) / 2);
    right: calc(var(--well-inset, 1.25rem) - (var(--well-copy) - 1rem) / 2);
