.home-hero :is(.home-hero-pill, .home-hero-actions .home-command) {
  --glass-fill: light-dark(#ffffff14, oklch(12% .012 70 / .28));
  --glass-top: light-dark(#ffffff29, #ffffff12);
  --glass-lip: light-dark(#fffffff2, #ffffff29);
  --glass-pool: light-dark(#ffffff38, #ffffff17);
  --glass-rim: light-dark(#fff, #ffffff8c);
  --glass-rim-far: light-dark(#ffffff8c, #ffffff29);
  --glass-glint: light-dark(oklch(84% .13 82 / .55), oklch(82% .13 82 / .32));
  --glass-glare: light-dark(oklch(99.5% .02 90 / .95), #fff6);
  isolation: isolate;
  background-color: var(--glass-fill);
  background-image: radial-gradient(ellipse 18% 30% at clamp(10%, var(--lit-x), 90%) 8%, color-mix(in oklab, var(--glass-glare) calc(var(--lit-near) * 100%), transparent), transparent),
    linear-gradient(180deg, var(--glass-top), transparent 50%);
  box-shadow: inset 0 1px 1px var(--glass-lip),
    inset 0 -10px 16px -12px var(--glass-pool),
    0 1px 2px light-dark(oklch(40% .06 70 / .1), #0000004d),
    /* Glass passes most of the light, so it casts a faint shadow; the canvas adds its caustic. */
    var(--cast-x) var(--cast-y) 16px -6px color-mix(in oklab, var(--cast-tone) 50%, transparent);
  backdrop-filter: blur(6px) saturate(1.35) brightness(1.06);
  transition: background-color var(--home-quick) var(--home-ease);
  border: 1px solid #0000;
  position: relative;

  &:before {
    z-index: -1;
    border-radius: inherit;
    background-image: linear-gradient(var(--lit-angle), var(--glass-rim-far), transparent 32%, transparent 62%, var(--glass-rim));
    pointer-events: none;
    content: "";
    padding: 1px;
    position: absolute;
    inset: -1px;
    mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
  }
}

