.home-editor-pointer {
  z-index: 4;
  top: calc(var(--editor-anchor-top) + var(--editor-pointer-rows) * var(--editor-row) + var(--editor-pointer-dy));
  left: calc(var(--editor-anchor-x) + var(--editor-pointer-dx));
