  stroke: var(--home-sheet);
  stroke-width: 1.25px;
  stroke-linejoin: round;
  filter: drop-shadow(0 1px 2px #00000047);
  opacity: 0;
  transform-origin: 4px 2.5px;
  transition: left .76s cubic-bezier(.45, .05, .25, 1), top .76s cubic-bezier(.6, 0, .3, 1), opacity .2s var(--home-ease), scale var(--home-quick) var(--home-ease);
  position: absolute;
  translate: -4px -2.5px;

  &[data-visible] {
    opacity: 1;
  }

  &[data-instant] {
    transition: opacity .2s var(--home-ease), scale var(--home-quick) var(--home-ease);
  }

  &[data-picker="original"] {
    left: calc(var(--editor-picker-x) + var(--editor-picker-effective-width) - 66px);
    top: calc(var(--editor-picker-y) + (var(--editor-picker-box) - var(--editor-picker-plane-height) - 2 * var(--editor-picker-inset)) / 2);
  }

  &[data-picker="plane"] {
    left: calc(var(--editor-picker-x) + var(--editor-picker-inset) + var(--editor-pointer-u) * var(--editor-picker-plane-width));
    top: calc(var(--editor-anchor-top) - var(--editor-picker-inset) - var(--editor-pointer-v) * var(--editor-picker-plane-height));
  }

  &[data-pressed] {
    scale: .86;
  }
}

