    vertical-align: baseline;
    line-height: 1.6;
  }

  & :where(th, td):first-child {
    padding-inline-start: var(--prose-table-gutter, 0);
  }

  & :where(th, td):last-child {
    padding-inline-end: var(--prose-table-gutter, 0);
  }

  & :where(thead th) {
    padding-block: var(--spacing-xs) .625rem;
    border-bottom-color: var(--color-line-divider);
