  }

  & :where(tbody th) {
    color: var(--color-text-strong);
    font-weight: var(--font-weight-medium);
  }

  & :is(tbody tr:last-child th, tbody tr:last-child td) {
    border-bottom-width: 0 !important;
  }

  & :is(td, th) p {
    margin: 0;
  }

  & td p code {
    font-size: 85%;
  }

  & :is(tr, th, td, tbody, thead) {
    contain: size;
