    min-width: 0;
  }

  .home-agent-facts code {
    min-width: 0;
    max-width: 100%;
  }

  .home-agent-hash {
    min-width: 0;
  }

  .home-agent-problem-meta {
    white-space: normal;
    overflow-wrap: anywhere;
  }

  .home-agent-token {
    grid-template-columns: minmax(0, 1fr);
    gap: 0;
  }

  .home-agent-token-bar {
    display: none;
  }

  .home-agent-panel-header {
    flex-wrap: wrap;
  }

  .home-agent-panel-tool {
    white-space: normal;
    overflow-wrap: anywhere;
    flex-basis: 100%;
    margin-left: 0;
  }

  .home-agent-steps {
    padding-inline: var(--home-agent-inset);
    flex-wrap: wrap;
    align-items: flex-start;
  }

  .home-agent-play {
    width: 44px;
    height: 44px;
  }

  .home-agent-step-list {
    flex: 1 0 100%;
    grid-template-columns: minmax(0, 1fr);
