cssSegments.ff8b54a1c5020911:
.home-wf-routes-tabs {
  --home-segment-pad: 3px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  width: min(100%, 14.25rem);
  margin-bottom: 1rem;
  display: inline-grid;

  &:before {
    content: "";
    z-index: -1;
    inset-block: var(--home-segment-pad);
    left: var(--home-segment-pad);
    width: calc((100% - var(--home-segment-pad) * 2) / 3);
    border-radius: inherit;
    background-color: light-dark(var(--home-sheet), color-mix(in oklab, var(--home-sheet) 86%, white));
    box-shadow: 0 0 0 1px var(--home-hairline), var(--home-contact), inset 0 1px 0 var(--home-highlight);
    transition: translate var(--home-base) var(--home-ease);
    position: absolute;
    translate: 0;
  }

  &:has([value="1"]:checked):before {
    translate: 100%;
  }

  &:has([value="2"]:checked):before {
    translate: 200%;
  }
}

